const TGC_VISUAL_STORIES={"planar":[{"title":"Cruzamento não prova não planaridade","frames":[{"label":"1. Situação inicial","note":"O desenho de K₄ foi feito com diagonais cruzadas.","boards":[{"name":"Grafo inicial","graph":"k4x"}]},{"label":"2. Investigue","note":"A adjacência não depende da posição dos pontos; observe as seis arestas.","boards":[{"name":"O que importa","graph":"k4x","focus":["a-c","b-d"]}]},{"label":"3. Transforme","note":"Mova d para dentro do triângulo abc, preservando todas as arestas.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"K₄ admite desenho sem cruzamentos. Logo, K₄ é planar.","boards":[{"name":"Antes","graph":"k4x"},{"name":"Depois","graph":"k4","focus":[]}]}]},{"title":"Conte faces pela fórmula de Euler","frames":[{"label":"1. Situação inicial","note":"No K₄ planar, identifique os quatro vértices e seis arestas.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Cada uma das três regiões internas e a região exterior é uma face.","boards":[{"name":"O que importa","graph":"k4","focus":[]}]},{"label":"3. Transforme","note":"Conte todas as faces no desenho planar, inclusive a externa.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"v−e+f=4−6+4=2. O teste depende da representação planar.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":[]}]}]},{"title":"Uma obstrução: K₃,₃","frames":[{"label":"1. Situação inicial","note":"Separe os três vértices de cada classe.","boards":[{"name":"Grafo inicial","graph":"k33"}]},{"label":"2. Investigue","note":"Todos os nove pares entre as classes são arestas. É bipartido.","boards":[{"name":"O que importa","graph":"k33","focus":[]}]},{"label":"3. Transforme","note":"Use o limite e≤2v−4 aplicável a grafos bipartidos planares simples.","boards":[{"name":"Após a operação","graph":"k33","focus":[]}]},{"label":"4. Demonstre","note":"K₃,₃ tem 6 vértices e 9 arestas, mas 2·6−4=8: não é planar.","boards":[{"name":"Antes","graph":"k33"},{"name":"Depois","graph":"k33","focus":[]}]}]},{"title":"Dualidade geométrica do K₄","frames":[{"label":"1. Situação inicial","note":"Parta de um desenho planar do K₄.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Há quatro faces, contando a exterior.","boards":[{"name":"O que importa","graph":"k4","focus":[]}]},{"label":"3. Transforme","note":"Atribua um novo vértice a cada face; una faces que compartilham aresta.","boards":[{"name":"Após a operação","graph":"dualk4","focus":[]}]},{"label":"4. Demonstre","note":"O dual geométrico deste desenho do K₄ é isomorfo a K₄. Os rótulos f representam faces.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"dualk4","focus":[]}]}]}],"sets":[{"title":"Selecione vértices independentes","frames":[{"label":"1. Situação inicial","note":"No caminho P₄, as arestas são ab, bc e cd.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Procure vértices sem uma aresta ligando os selecionados.","boards":[{"name":"O que importa","graph":"p4","focus":[]}]},{"label":"3. Transforme","note":"Marque a e c como integrantes de S.","boards":[{"name":"Após a operação","graph":"p4ind","focus":["a-b","b-c"]}]},{"label":"4. Demonstre","note":"S={a,c} é independente e tem tamanho 2.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p4ind","focus":["a-b","b-c"]}]}]},{"title":"Maximal não significa máximo","frames":[{"label":"1. Situação inicial","note":"Na estrela K₁,₃, o centro o é adjacente às três folhas.","boards":[{"name":"Grafo inicial","graph":"star3center"}]},{"label":"2. Investigue","note":"{o} é independente maximal: não pode receber outra folha.","boards":[{"name":"O que importa","graph":"star3center","focus":[]}]},{"label":"3. Transforme","note":"Remova o da seleção e escolha as três folhas.","boards":[{"name":"Após a operação","graph":"star3leaves","focus":[]}]},{"label":"4. Demonstre","note":"{a,b,c} é independente de tamanho 3. Assim, o maximal {o} não é máximo.","boards":[{"name":"Antes","graph":"star3center"},{"name":"Depois","graph":"star3leaves","focus":[]}]}]},{"title":"Cobertura e complemento independente","frames":[{"label":"1. Situação inicial","note":"P₄ possui três arestas. Cada aresta deve tocar a cobertura.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Escolha os vértices internos b e c.","boards":[{"name":"O que importa","graph":"p4","focus":[]}]},{"label":"3. Transforme","note":"A cobertura C={b,c} toca ab, bc e cd.","boards":[{"name":"Após a operação","graph":"p4cover","focus":[]}]},{"label":"4. Demonstre","note":"V\\C={a,d} é independente, e α(P₄)+τ(P₄)=2+2=4.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p4cover","focus":[]}]}]},{"title":"Troque grafo por complemento","frames":[{"label":"1. Situação inicial","note":"Em P₄, a e c não são adjacentes.","boards":[{"name":"Grafo inicial","graph":"p4ind"}]},{"label":"2. Investigue","note":"No complemento, cada par antes não adjacente passa a ter aresta.","boards":[{"name":"O que importa","graph":"p4ind","focus":[]}]},{"label":"3. Transforme","note":"Construa as arestas ac, ad e bd.","boards":[{"name":"Após a operação","graph":"complp4","focus":["a-c"]}]},{"label":"4. Demonstre","note":"{a,c} é independente no original e clique no complemento.","boards":[{"name":"Antes","graph":"p4ind"},{"name":"Depois","graph":"complp4","focus":["a-c"]}]}]}],"color":[{"title":"Por que um ciclo ímpar não cabe em 2 cores?","frames":[{"label":"1. Situação inicial","note":"Tente alternar duas cores ao redor de C₅.","boards":[{"name":"Grafo inicial","graph":"c5bad"}]},{"label":"2. Investigue","note":"A quinta posição volta a colidir com a primeira pela aresta ea.","boards":[{"name":"O que importa","graph":"c5bad","focus":["e-a"]}]},{"label":"3. Transforme","note":"Mude apenas a quinta cor para uma terceira cor.","boards":[{"name":"Após a operação","graph":"c5good","focus":[]}]},{"label":"4. Demonstre","note":"O triângulo não é necessário: a paridade impede 2; a coloração prova χ(C₅)=3.","boards":[{"name":"Antes","graph":"c5bad"},{"name":"Depois","graph":"c5good","focus":[]}]}]},{"title":"Clique fornece limite inferior","frames":[{"label":"1. Situação inicial","note":"Em K₄, todo par de vértices é adjacente.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Uma clique de quatro exige quatro cores diferentes.","boards":[{"name":"O que importa","graph":"k4","focus":{}}]},{"label":"3. Transforme","note":"Atribua quatro cores distintas a seus quatro vértices.","boards":[{"name":"Após a operação","graph":"k4","focus":{}}]},{"label":"4. Demonstre","note":"O limite inferior e uma coloração válida coincidem: χ(K₄)=4.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":{}}]}]},{"title":"Construa uma coloração própria","frames":[{"label":"1. Situação inicial","note":"No caminho P₄, percorra os vértices da esquerda para a direita.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Cada novo vértice precisa diferir dos vizinhos já coloridos.","boards":[{"name":"O que importa","graph":"p4","focus":[]}]},{"label":"3. Transforme","note":"Alterne 1,2,1,2.","boards":[{"name":"Após a operação","graph":"p4colored","focus":[]}]},{"label":"4. Demonstre","note":"Duas cores bastam. Uma aresta impede usar somente uma, logo χ(P₄)=2.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p4colored","focus":[]}]}]},{"title":"Coloração de arestas vira coloração de vértices","frames":[{"label":"1. Situação inicial","note":"Na estrela K₁,₃, três arestas compartilham o centro.","boards":[{"name":"Grafo inicial","graph":"star3edges"}]},{"label":"2. Investigue","note":"Essas arestas exigem três cores diferentes.","boards":[{"name":"O que importa","graph":"star3edges","focus":[]}]},{"label":"3. Transforme","note":"Faça cada aresta virar um vértice de L(G); o resultado é K₃.","boards":[{"name":"Após a operação","graph":"lc3color","focus":[]}]},{"label":"4. Demonstre","note":"Assim χ′(K₁,₃)=χ(K₃)=3.","boards":[{"name":"Antes","graph":"star3edges"},{"name":"Depois","graph":"lc3color","focus":[]}]}]}],"euler":[{"title":"Trilha euleriana olha arestas","frames":[{"label":"1. Situação inicial","note":"No caminho P₄, os extremos têm grau 1 e os internos grau 2.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Identifique os dois únicos vértices de grau ímpar.","boards":[{"name":"O que importa","graph":"p4","focus":["a-b","b-c","c-d"]}]},{"label":"3. Transforme","note":"Percorra ab, bc, cd uma vez cada.","boards":[{"name":"Após a operação","graph":"p4matching","focus":[]}]},{"label":"4. Demonstre","note":"Existe trilha euleriana aberta de a até d, mas não circuito euleriano.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p4matching","focus":[]}]}]},{"title":"Hamilton não implica Euler","frames":[{"label":"1. Situação inicial","note":"K₄ possui ciclo que visita seus quatro vértices e retorna.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Cada vértice de K₄, no entanto, tem grau 3.","boards":[{"name":"O que importa","graph":"k4","focus":["a-b","b-c","c-d","d-a"]}]},{"label":"3. Transforme","note":"Use o ciclo a→b→c→d→a como testemunha hamiltoniana.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"K₄ tem ciclo hamiltoniano e não possui circuito euleriano.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":[]}]}]},{"title":"Remover uma ponte aumenta as componentes","frames":[{"label":"1. Situação inicial","note":"No triângulo abc com cauda cd, a aresta cd não pertence a ciclo.","boards":[{"name":"Grafo inicial","graph":"tail"}]},{"label":"2. Investigue","note":"Ao remover ab, ainda há caminho alternativo a→c→b.","boards":[{"name":"O que importa","graph":"tail","focus":["c-d"]}]},{"label":"3. Transforme","note":"Remova cd: d fica isolado.","boards":[{"name":"Após a operação","graph":"tailcut","focus":[]}]},{"label":"4. Demonstre","note":"A retirada de cd aumenta o número de componentes: cd é ponte.","boards":[{"name":"Antes","graph":"tail"},{"name":"Depois","graph":"tailcut","focus":[]}]}]},{"title":"Contraexemplo é prova de falsidade","frames":[{"label":"1. Situação inicial","note":"Na estrela K₁,₃, o centro tem grau 3 e as três folhas grau 1.","boards":[{"name":"Grafo inicial","graph":"star3"}]},{"label":"2. Investigue","note":"São quatro vértices ímpares, impossibilitando trilha euleriana.","boards":[{"name":"O que importa","graph":"star3","focus":[]}]},{"label":"3. Transforme","note":"Compare com C₄, onde todos os graus são pares.","boards":[{"name":"Após a operação","graph":"c4","focus":[]}]},{"label":"4. Demonstre","note":"Paridade e conexidade, não aparência, decidem a existência de circuito euleriano.","boards":[{"name":"Antes","graph":"star3"},{"name":"Depois","graph":"c4","focus":[]}]}]}],"line":[{"title":"Aresta vira vértice","frames":[{"label":"1. Situação inicial","note":"Em K₁,₃, nomeie as três arestas e₁, e₂, e₃.","boards":[{"name":"Grafo inicial","graph":"star3"}]},{"label":"2. Investigue","note":"Todas as três arestas têm o centro em comum.","boards":[{"name":"O que importa","graph":"star3","focus":[]}]},{"label":"3. Transforme","note":"Transforme cada uma em um vértice e ligue pares incidentes.","boards":[{"name":"Após a operação","graph":"lc3","focus":[]}]},{"label":"4. Demonstre","note":"L(K₁,₃)=K₃. Um grafo acíclico pode gerar grafo de linha cíclico.","boards":[{"name":"Antes","graph":"star3"},{"name":"Depois","graph":"lc3","focus":[]}]}]},{"title":"Construa L(P₄)","frames":[{"label":"1. Situação inicial","note":"P₄ possui três arestas consecutivas.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"A primeira compartilha extremidade com a segunda, mas não com a terceira.","boards":[{"name":"O que importa","graph":"p4","focus":[]}]},{"label":"3. Transforme","note":"Crie e₁,e₂,e₃ e ligue apenas os pares incidentes.","boards":[{"name":"Após a operação","graph":"p3line","focus":[]}]},{"label":"4. Demonstre","note":"L(P₄)=P₃.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p3line","focus":[]}]}]},{"title":"Planaridade pode deixar de valer","frames":[{"label":"1. Situação inicial","note":"K₁,₅ é uma árvore, logo planar.","boards":[{"name":"Grafo inicial","graph":"star5"}]},{"label":"2. Investigue","note":"As cinco arestas compartilham o centro.","boards":[{"name":"O que importa","graph":"star5","focus":[]}]},{"label":"3. Transforme","note":"No grafo de linha, cada novo vértice é adjacente aos outros quatro.","boards":[{"name":"Após a operação","graph":"lc5","focus":[]}]},{"label":"4. Demonstre","note":"L(K₁,₅)=K₅, que é não planar.","boards":[{"name":"Antes","graph":"star5"},{"name":"Depois","graph":"lc5","focus":[]}]}]},{"title":"Uma transformação que preserva C₄","frames":[{"label":"1. Situação inicial","note":"C₄ tem quatro arestas com incidências cíclicas.","boards":[{"name":"Grafo inicial","graph":"c4"}]},{"label":"2. Investigue","note":"Cada aresta é incidente às duas vizinhas.","boards":[{"name":"O que importa","graph":"c4","focus":[]}]},{"label":"3. Transforme","note":"Faça cada aresta original virar um vértice.","boards":[{"name":"Após a operação","graph":"lc4","focus":[]}]},{"label":"4. Demonstre","note":"L(C₄) é isomorfo a C₄. Aqui a forma geral é preservada.","boards":[{"name":"Antes","graph":"c4"},{"name":"Depois","graph":"lc4","focus":[]}]}]}],"trees":[{"title":"Quebre um ciclo para obter árvore","frames":[{"label":"1. Situação inicial","note":"C₄ é conexo, mas contém ciclo.","boards":[{"name":"Grafo inicial","graph":"c4"}]},{"label":"2. Investigue","note":"Uma árvore de quatro vértices precisa de três arestas sem ciclo.","boards":[{"name":"O que importa","graph":"c4","focus":["d-a"]}]},{"label":"3. Transforme","note":"Retire a aresta da, preservando o caminho a−b−c−d.","boards":[{"name":"Após a operação","graph":"c4cut","focus":[]}]},{"label":"4. Demonstre","note":"O resultado é conexo e acíclico: uma árvore geradora.","boards":[{"name":"Antes","graph":"c4"},{"name":"Depois","graph":"c4cut","focus":[]}]}]},{"title":"Toda aresta de árvore é ponte","frames":[{"label":"1. Situação inicial","note":"Na árvore caminho P₄ existe um caminho único entre cada par.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Retirar a aresta bc não deixa rota alternativa entre b e c.","boards":[{"name":"O que importa","graph":"p4","focus":["b-c"]}]},{"label":"3. Transforme","note":"Compare com cd do triângulo com cauda, outra ponte.","boards":[{"name":"Após a operação","graph":"tail","focus":["c-d"]}]},{"label":"4. Demonstre","note":"Aresta em ciclo não é ponte; aresta de árvore é ponte.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"tail","focus":["c-d"]}]}]},{"title":"Contagem de árvores geradoras em C₄","frames":[{"label":"1. Situação inicial","note":"C₄ possui quatro arestas e quatro vértices.","boards":[{"name":"Grafo inicial","graph":"c4"}]},{"label":"2. Investigue","note":"Uma árvore geradora exige n−1=3 arestas.","boards":[{"name":"O que importa","graph":"c4","focus":[]}]},{"label":"3. Transforme","note":"Remova uma das quatro arestas do ciclo.","boards":[{"name":"Após a operação","graph":"c4cut","focus":[]}]},{"label":"4. Demonstre","note":"Há quatro escolhas distintas da aresta removida, logo quatro árvores geradoras.","boards":[{"name":"Antes","graph":"c4"},{"name":"Depois","graph":"c4cut","focus":[]}]}]},{"title":"AGM por escolha de arestas leves","frames":[{"label":"1. Situação inicial","note":"No grafo ponderado, os custos são indicados em cada arco.","boards":[{"name":"Grafo inicial","graph":"weighted"}]},{"label":"2. Investigue","note":"Ignore o sentido apenas neste desenho usado como grafo subjacente não direcionado.","boards":[{"name":"O que importa","graph":"weighted","focus":[]}]},{"label":"3. Transforme","note":"Selecione ab(1), sa(2), bt(2) sem criar ciclo.","boards":[{"name":"Após a operação","graph":"weightedFocus","focus":[]}]},{"label":"4. Demonstre","note":"Essas três arestas ligam os quatro vértices com custo total 5, mínimo pelo critério de Kruskal.","boards":[{"name":"Antes","graph":"weighted"},{"name":"Depois","graph":"weightedFocus","focus":[]}]}]}],"shortest":[{"title":"Faça uma relaxação","frames":[{"label":"1. Situação inicial","note":"Na rede dirigida, comece com d[s]=0 e os demais em infinito.","boards":[{"name":"Grafo inicial","graph":"weighted"}]},{"label":"2. Investigue","note":"A aresta s→a de custo 2 permite melhorar d[a].","boards":[{"name":"O que importa","graph":"weighted","focus":["s-a","a-b"]}]},{"label":"3. Transforme","note":"Relaxe a→b de custo 1, após alcançar a.","boards":[{"name":"Após a operação","graph":"weightedFocus","focus":[]}]},{"label":"4. Demonstre","note":"Obtemos d[a]=2 e d[b]≤3; sempre atualize o destino da aresta.","boards":[{"name":"Antes","graph":"weighted"},{"name":"Depois","graph":"weightedFocus","focus":[]}]}]},{"title":"Dijkstra fecha distâncias não negativas","frames":[{"label":"1. Situação inicial","note":"Todos os pesos da rede são não negativos.","boards":[{"name":"Grafo inicial","graph":"weighted"}]},{"label":"2. Investigue","note":"Fixe s=0, depois a=2, b=3, t=5.","boards":[{"name":"O que importa","graph":"weighted","focus":[]}]},{"label":"3. Transforme","note":"A árvore de predecessores inclui s→a, a→b, b→t.","boards":[{"name":"Após a operação","graph":"weightedFocus","focus":[]}]},{"label":"4. Demonstre","note":"As distâncias mínimas são (0,2,3,5) para (s,a,b,t).","boards":[{"name":"Antes","graph":"weighted"},{"name":"Depois","graph":"weightedFocus","focus":[]}]}]},{"title":"Bellman-Ford aceita pesos negativos","frames":[{"label":"1. Situação inicial","note":"A aresta a→b tem custo negativo −4.","boards":[{"name":"Grafo inicial","graph":"weighted"}]},{"label":"2. Investigue","note":"Dijkstra não tem garantia para esse cenário.","boards":[{"name":"O que importa","graph":"weighted","focus":["a-b"]}]},{"label":"3. Transforme","note":"Relaxe s→a (2), a→b (−4), b→t (2).","boards":[{"name":"Após a operação","graph":"negative","focus":["a-b"]}]},{"label":"4. Demonstre","note":"O menor custo s→t é 0. Não há ciclos dirigidos nesta rede.","boards":[{"name":"Antes","graph":"weighted"},{"name":"Depois","graph":"negative","focus":["a-b"]}]}]},{"title":"Maior caminho em DAG não é Dijkstra invertido","frames":[{"label":"1. Situação inicial","note":"A rede não possui ciclos dirigidos.","boards":[{"name":"Grafo inicial","graph":"weighted"}]},{"label":"2. Investigue","note":"Para maior caminho em DAG, processe uma ordem topológica.","boards":[{"name":"O que importa","graph":"weighted","focus":[]}]},{"label":"3. Transforme","note":"No exemplo, s→a→t tem custo 2+6=8.","boards":[{"name":"Após a operação","graph":"weightedLong","focus":[]}]},{"label":"4. Demonstre","note":"Compare com s→b→t=7 e s→a→b→t=5; o maior é 8.","boards":[{"name":"Antes","graph":"weighted"},{"name":"Depois","graph":"weightedLong","focus":[]}]}]}],"bipart":[{"title":"Duas classes sem arestas internas","frames":[{"label":"1. Situação inicial","note":"K₂,₃ tem partição {a,b} e {x,y,z}.","boards":[{"name":"Grafo inicial","graph":"k23"}]},{"label":"2. Investigue","note":"Arestas ligam somente uma classe à outra.","boards":[{"name":"O que importa","graph":"k23","focus":[]}]},{"label":"3. Transforme","note":"Marque as duas classes com cores distintas.","boards":[{"name":"Após a operação","graph":"k23","focus":[]}]},{"label":"4. Demonstre","note":"Não há ciclo ímpar; K₂,₃ é bipartido e tem 2·3=6 arestas.","boards":[{"name":"Antes","graph":"k23"},{"name":"Depois","graph":"k23","focus":[]}]}]},{"title":"Conte arestas entre três partes","frames":[{"label":"1. Situação inicial","note":"K₂,₂,₂ tem três grupos de dois vértices cada.","boards":[{"name":"Grafo inicial","graph":"k222"}]},{"label":"2. Investigue","note":"Não existem arestas dentro de cada grupo.","boards":[{"name":"O que importa","graph":"k222","focus":[]}]},{"label":"3. Transforme","note":"Conte 2·2 entre o primeiro e o segundo, repetindo para cada par de grupos.","boards":[{"name":"Após a operação","graph":"k222","focus":[]}]},{"label":"4. Demonstre","note":"São 4+4+4=12 arestas para seis vértices.","boards":[{"name":"Antes","graph":"k222"},{"name":"Depois","graph":"k222","focus":[]}]}]},{"title":"Induzido preserva todas as arestas internas","frames":[{"label":"1. Situação inicial","note":"No P₄, escolha S={b,c,d}.","boards":[{"name":"Grafo inicial","graph":"p4"}]},{"label":"2. Investigue","note":"Ao induzir o subgrafo, eliminamos o vértice a.","boards":[{"name":"O que importa","graph":"p4","focus":[]}]},{"label":"3. Transforme","note":"As arestas bc e cd permanecem automaticamente.","boards":[{"name":"Após a operação","graph":"p3bcd","focus":[]}]},{"label":"4. Demonstre","note":"O subgrafo induzido por S é P₃ sobre b,c,d.","boards":[{"name":"Antes","graph":"p4"},{"name":"Depois","graph":"p3bcd","focus":[]}]}]},{"title":"Lema do aperto de mãos","frames":[{"label":"1. Situação inicial","note":"K₄ é 3-regular: cada vértice toca três arestas.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"A soma dos quatro graus é 3+3+3+3=12.","boards":[{"name":"O que importa","graph":"k4","focus":[]}]},{"label":"3. Transforme","note":"Conte suas seis arestas; cada aresta contribui duas incidências.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"∑graus=12=2·6. Portanto |E|=nk/2 para grafos k-regulares.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":[]}]}]}],"matching":[{"title":"Selecione arestas que não compartilham vértices","frames":[{"label":"1. Situação inicial","note":"O grafo bipartido tem três vértices em cada lado.","boards":[{"name":"Grafo inicial","graph":"match"}]},{"label":"2. Investigue","note":"Uma aresta selecionada ocupa seus dois extremos.","boards":[{"name":"O que importa","graph":"match","focus":[]}]},{"label":"3. Transforme","note":"Escolha u₁v₁, u₂v₂ e u₃v₃.","boards":[{"name":"Após a operação","graph":"matchSelect","focus":[]}]},{"label":"4. Demonstre","note":"Três pares disjuntos formam matching de tamanho 3; é máximo pois só há três vértices de cada lado.","boards":[{"name":"Antes","graph":"match"},{"name":"Depois","graph":"matchSelect","focus":[]}]}]},{"title":"Matching maximal pode ser menor que máximo","frames":[{"label":"1. Situação inicial","note":"No caminho P₄, a aresta central bc sozinha forma matching maximal.","boards":[{"name":"Grafo inicial","graph":"p4center"}]},{"label":"2. Investigue","note":"Nenhuma outra aresta é disjunta de bc.","boards":[{"name":"O que importa","graph":"p4center","focus":[]}]},{"label":"3. Transforme","note":"Troque bc por ab e cd, que são disjuntas.","boards":[{"name":"Após a operação","graph":"p4matching","focus":[]}]},{"label":"4. Demonstre","note":"O maximal tem tamanho 1, mas o máximo tem tamanho 2.","boards":[{"name":"Antes","graph":"p4center"},{"name":"Depois","graph":"p4matching","focus":[]}]}]},{"title":"Kőnig em bipartidos","frames":[{"label":"1. Situação inicial","note":"K₂,₃ possui duas partes e todas as seis arestas entre elas.","boards":[{"name":"Grafo inicial","graph":"k23"}]},{"label":"2. Investigue","note":"Qualquer matching usa no máximo dois vértices do lado menor.","boards":[{"name":"O que importa","graph":"k23","focus":[]}]},{"label":"3. Transforme","note":"Cobrir ambos os vértices do lado menor cobre todas as arestas.","boards":[{"name":"Após a operação","graph":"k23","focus":[]}]},{"label":"4. Demonstre","note":"Matching máximo=2 e cobertura mínima=2, como garante o teorema de Kőnig.","boards":[{"name":"Antes","graph":"k23"},{"name":"Depois","graph":"k23","focus":[]}]}]},{"title":"Matching é independente no grafo de linha","frames":[{"label":"1. Situação inicial","note":"Em P₄, ab e cd são arestas não incidentes.","boards":[{"name":"Grafo inicial","graph":"p4matching"}]},{"label":"2. Investigue","note":"No grafo de linha, elas se tornam e₁ e e₃, sem aresta entre si.","boards":[{"name":"O que importa","graph":"p4matching","focus":[]}]},{"label":"3. Transforme","note":"Transforme o P₄ em L(P₄)=P₃.","boards":[{"name":"Após a operação","graph":"p3matchline","focus":[]}]},{"label":"4. Demonstre","note":"{e₁,e₃} é um conjunto independente em L(P₄).","boards":[{"name":"Antes","graph":"p4matching"},{"name":"Depois","graph":"p3matchline","focus":[]}]}]}],"degrees":[{"title":"Aperto de mãos","frames":[{"label":"1. Situação inicial","note":"K₄ tem quatro vértices de grau 3.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Some os graus: 3+3+3+3=12.","boards":[{"name":"O que importa","graph":"k4","focus":[]}]},{"label":"3. Transforme","note":"Conte as seis arestas desenhadas.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"Cada aresta foi contada duas vezes: ∑graus=2|E|.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":[]}]}]},{"title":"Um grau impossível","frames":[{"label":"1. Situação inicial","note":"Um grafo simples com quatro vértices admite no máximo grau 3.","boards":[{"name":"Grafo inicial","graph":"k4"}]},{"label":"2. Investigue","note":"Em K₄, cada vértice já se liga a todos os outros.","boards":[{"name":"O que importa","graph":"k4","focus":[]}]},{"label":"3. Transforme","note":"Não é possível ter vértice de grau 4 sem laço ou aresta paralela.","boards":[{"name":"Após a operação","graph":"k4","focus":[]}]},{"label":"4. Demonstre","note":"A sequência (4,2,1,1) não é gráfica para grafo simples de quatro vértices.","boards":[{"name":"Antes","graph":"k4"},{"name":"Depois","graph":"k4","focus":[]}]}]},{"title":"Havel–Hakimi remove maior grau","frames":[{"label":"1. Situação inicial","note":"A sequência (3,3,2,2,2) soma 12, compatível com 6 arestas.","boards":[{"name":"Grafo inicial","graph":"havel"}]},{"label":"2. Investigue","note":"Reduza o primeiro 3 e retire uma unidade dos três graus seguintes.","boards":[{"name":"O que importa","graph":"havel","focus":[]}]},{"label":"3. Transforme","note":"A construção exibe as arestas ab, ac, ad, bc, be, de.","boards":[{"name":"Após a operação","graph":"havel","focus":[]}]},{"label":"4. Demonstre","note":"Os graus resultam (3,3,2,2,2), demonstrando que a sequência é gráfica.","boards":[{"name":"Antes","graph":"havel"},{"name":"Depois","graph":"havel","focus":[]}]}]},{"title":"Regularidade é igualdade de graus","frames":[{"label":"1. Situação inicial","note":"Em C₅, cada vértice tem exatamente dois vizinhos.","boards":[{"name":"Grafo inicial","graph":"c5"}]},{"label":"2. Investigue","note":"Logo C₅ é 2-regular, embora não seja completo.","boards":[{"name":"O que importa","graph":"c5","focus":[]}]},{"label":"3. Transforme","note":"A soma dos graus é 5·2=10.","boards":[{"name":"Após a operação","graph":"c5","focus":[]}]},{"label":"4. Demonstre","note":"Como cada aresta aparece duas vezes na soma, são 5 arestas.","boards":[{"name":"Antes","graph":"c5"},{"name":"Depois","graph":"c5","focus":[]}]}]}],"model":[{"title":"Decisões viram vértices","frames":[{"label":"1. Situação inicial","note":"Considere quatro movimentos hipotéticos R₁, R₂, R₃ e R₄.","boards":[{"name":"Grafo inicial","graph":"conflictPath"}]},{"label":"2. Investigue","note":"Cada movimento precisa receber uma fase de uso do cruzamento.","boards":[{"name":"O que importa","graph":"conflictPath","focus":[]}]},{"label":"3. Transforme","note":"Construa um vértice para cada movimento.","boards":[{"name":"Após a operação","graph":"conflictPath","focus":[]}]},{"label":"4. Demonstre","note":"O grafo de conflitos representa incompatibilidade, não a geometria real das ruas.","boards":[{"name":"Antes","graph":"conflictPath"},{"name":"Depois","graph":"conflictPath","focus":[]}]}]},{"title":"Conflitos viram arestas","frames":[{"label":"1. Situação inicial","note":"R₁, R₂ e R₃ são incompatíveis dois a dois, enquanto R₄ é compatível.","boards":[{"name":"Grafo inicial","graph":"conflictPath"}]},{"label":"2. Investigue","note":"Para cada par incompatível, desenhe uma aresta.","boards":[{"name":"O que importa","graph":"conflictPath","focus":[]}]},{"label":"3. Transforme","note":"O subgrafo sobre R₁,R₂,R₃ é K₃.","boards":[{"name":"Após a operação","graph":"conflict","focus":[]}]},{"label":"4. Demonstre","note":"Um triângulo de conflitos implica pelo menos três fases.","boards":[{"name":"Antes","graph":"conflictPath"},{"name":"Depois","graph":"conflict","focus":[]}]}]},{"title":"Cores representam fases","frames":[{"label":"1. Situação inicial","note":"No caminho de conflitos R₁−R₂−R₃−R₄, há adjacências apenas consecutivas.","boards":[{"name":"Grafo inicial","graph":"conflictPath"}]},{"label":"2. Investigue","note":"Não há conflitos entre R₁ e R₃, nem entre R₂ e R₄.","boards":[{"name":"O que importa","graph":"conflictPath","focus":[]}]},{"label":"3. Transforme","note":"Agrupe R₁,R₃ na fase 1 e R₂,R₄ na fase 2.","boards":[{"name":"Após a operação","graph":"conflictPathColor","focus":[]}]},{"label":"4. Demonstre","note":"Duas cores formam uma escala válida, e uma aresta impede fase única.","boards":[{"name":"Antes","graph":"conflictPath"},{"name":"Depois","graph":"conflictPathColor","focus":[]}]}]},{"title":"Comprove que o número de fases é mínimo","frames":[{"label":"1. Situação inicial","note":"Três movimentos formam uma clique K₃ no grafo de conflitos.","boards":[{"name":"Grafo inicial","graph":"conflict"}]},{"label":"2. Investigue","note":"Isso força pelo menos três cores.","boards":[{"name":"O que importa","graph":"conflict","focus":[]}]},{"label":"3. Transforme","note":"Colora R₁,R₂,R₃ com cores distintas e coloque R₄ na primeira fase.","boards":[{"name":"Após a operação","graph":"conflictColor","focus":[]}]},{"label":"4. Demonstre","note":"Há coloração com três cores e limite inferior 3: χ=3.","boards":[{"name":"Antes","graph":"conflict"},{"name":"Depois","graph":"conflictColor","focus":[]}]}]}],"flow":[{"title":"Capacidades em uma rede","frames":[{"label":"1. Situação inicial","note":"Na rede dirigida, s é a fonte e t o destino.","boards":[{"name":"Grafo inicial","graph":"flow"}]},{"label":"2. Investigue","note":"Os números das arestas representam capacidades máximas.","boards":[{"name":"O que importa","graph":"flow","focus":[]}]},{"label":"3. Transforme","note":"Compare os arcos de saída s→a=3 e s→b=2.","boards":[{"name":"Após a operação","graph":"flow","focus":[]}]},{"label":"4. Demonstre","note":"A rede pode enviar no máximo 5 unidades de s, antes de analisar outros gargalos.","boards":[{"name":"Antes","graph":"flow"},{"name":"Depois","graph":"flow","focus":[]}]}]},{"title":"Aumente fluxo por um caminho","frames":[{"label":"1. Situação inicial","note":"No início todas as arestas transportam fluxo 0.","boards":[{"name":"Grafo inicial","graph":"flow"}]},{"label":"2. Investigue","note":"O caminho s→a→t tem capacidades 3 e 2.","boards":[{"name":"O que importa","graph":"flow","focus":["s-a","a-t"]}]},{"label":"3. Transforme","note":"Envie 2 unidades, o mínimo dessas capacidades.","boards":[{"name":"Após a operação","graph":"flowAug","focus":["s-a","a-t"]}]},{"label":"4. Demonstre","note":"O arco a→t satura; a rede residual permite examinar novas rotas.","boards":[{"name":"Antes","graph":"flow"},{"name":"Depois","graph":"flowAug","focus":["s-a","a-t"]}]}]},{"title":"Certifique com um corte","frames":[{"label":"1. Situação inicial","note":"Considere o corte S={s}, T={a,b,t}.","boards":[{"name":"Grafo inicial","graph":"flow"}]},{"label":"2. Investigue","note":"Somam-se apenas as capacidades das arestas saindo de S.","boards":[{"name":"O que importa","graph":"flow","focus":[]}]},{"label":"3. Transforme","note":"As duas arestas de saída têm capacidades 3 e 2.","boards":[{"name":"Após a operação","graph":"flowCut","focus":["s-a","s-b"]}]},{"label":"4. Demonstre","note":"O corte vale 5. O fluxo 5 é viável: s→a→t (2), s→a→b→t (1), s→b→t (2). Logo é máximo.","boards":[{"name":"Antes","graph":"flow"},{"name":"Depois","graph":"flowCut","focus":["s-a","s-b"]}]}]},{"title":"Matching como fluxo em bipartidos","frames":[{"label":"1. Situação inicial","note":"Para relacionar matching e fluxo, imagine arcos de capacidade 1.","boards":[{"name":"Grafo inicial","graph":"match"}]},{"label":"2. Investigue","note":"Cada par escolhido transporta uma unidade entre classes.","boards":[{"name":"O que importa","graph":"match","focus":[]}]},{"label":"3. Transforme","note":"Escolha três pares disjuntos no grafo bipartido.","boards":[{"name":"Após a operação","graph":"matchSelect","focus":[]}]},{"label":"4. Demonstre","note":"Na redução de matching, ligam-se fonte à classe esquerda e classe direita ao sorvedouro.","boards":[{"name":"Antes","graph":"match"},{"name":"Depois","graph":"matchSelect","focus":[]}]}]}]};
function visEsc(x){return String(x??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function visualGetData(id,step){return TGC_VISUAL_STORIES[id]?.[step]||null}
function visualEdgeKey(e){return e.a+"-"+e.b}
function visualDrawGraph(board,vid,key,phase){
 const g=TGC_VISUAL_GRAPHS[board.graph];if(!g)return '';
 const build=progress.visualBuild?.[key+":"+phase+":"+board.graph]||null;
 const shown=g.edges.filter((e)=>build===null||build.includes(visualEdgeKey(e)));
 const highlight=new Set([...(g.focusEdges||[]),...((board.focus&&Array.isArray(board.focus))?board.focus:[])]);
 const ncolors=['','var(--blue)','var(--orange)','var(--accent)','var(--yellow)','var(--red)'];
 const nids=Object.keys(g.nodes);
 const colors=g.colors||{};
 const defs='<defs><marker id="'+vid+'-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="var(--muted)"/></marker></defs>';
 let paths='';
 g.edges.forEach((e,i)=>{
  const a=g.nodes[e.a],b=g.nodes[e.b];if(!a||!b)return;const id=visualEdgeKey(e),active=build===null||build.includes(id);const dx=b[0]-a[0],dy=b[1]-a[1],length=Math.hypot(dx,dy)||1,ux=dx/length,uy=dy/length;
  const from=[a[0]+ux*17,a[1]+uy*17],to=[b[0]-ux*20,b[1]-uy*20];
  const focus=highlight.has(id)||highlight.has(e.b+"-"+e.a);
  const arrow=g.directed?' marker-end="url(#'+vid+'-arrow)"':'';
  const onClick='data-v-action="edge" data-v-edge="'+visEsc(id)+'" data-v-key="'+visEsc(key)+'" data-v-phase="'+phase+'" data-v-board="'+visEsc(board.graph)+'"';
  const sw=focus?4:2.25,stroke=focus?'var(--accent)':'var(--muted)';
  paths+='<g role="button" tabindex="0" aria-label="Alternar aresta '+visEsc(e.a)+'–'+visEsc(e.b)+'" '+onClick+'><path d="M'+from.join(',')+' L'+to.join(',')+'" fill="none" stroke="'+stroke+'" stroke-width="'+sw+'" stroke-dasharray="'+(active?'none':'5 7')+'" opacity="'+(active?'0.9':'0.25')+'"'+arrow+'/><path d="M'+a.join(',')+' L'+b.join(',')+'" stroke="transparent" stroke-width="19" fill="none"/>';
  if(e.w!==null){const px=(a[0]+b[0])/2-uy*15,py=(a[1]+b[1])/2+ux*15;paths+='<text x="'+px+'" y="'+py+'" class="visual-weight">'+visEsc(e.w)+'</text>'}
  paths+='</g>';
 });
 const nodes=nids.map((id)=>{const [x,y]=g.nodes[id],sel=window.TGC_VISUAL_PICK===key+":"+phase+":"+id;
 return '<g data-v-action="node" data-v-node="'+visEsc(id)+'" data-v-key="'+visEsc(key)+'" data-v-phase="'+phase+'" data-v-board="'+visEsc(board.graph)+'" role="button" tabindex="0" aria-label="Selecionar vértice '+visEsc(id)+'"><circle cx="'+x+'" cy="'+y+'" r="17" fill="'+(ncolors[colors[id]||0]||'var(--panel3)')+'" stroke="'+(sel?'var(--yellow)':'var(--blue)')+'" stroke-width="'+(sel?4:2)+'"/><text x="'+x+'" y="'+(y+4.3)+'" class="visual-node-label" style="fill:'+(colors[id]?'var(--bg)':'var(--text)')+'">'+visEsc(id)+'</text></g>'}).join('');
 const count=shown.length,comps=(()=>{const adj=Object.fromEntries(nids.map(id=>[id,[]]));for(const e of shown){adj[e.a].push(e.b);adj[e.b].push(e.a)}const visited=new Set;let c=0;for(const id of nids){if(visited.has(id))continue;c++;const stack=[id];visited.add(id);while(stack.length){for(const n of adj[stack.pop()])if(!visited.has(n)){visited.add(n);stack.push(n)}}}return c})();
 const selected=(window.TGC_VISUAL_PICK||'').startsWith(key+":"+phase+":")?(window.TGC_VISUAL_PICK.split(":").at(-1)):null;
 const degree=selected?shown.reduce((acc,e)=>acc+(e.a===selected||e.b===selected?1:0),0):null;
 const subtitle='|V| = '+nids.length+' · |E| = '+count+' · componentes = '+comps+(selected?' · grau('+selected+') = '+degree:'');
 return '<div class="visual-board"><div class="visual-board-label">'+visEsc(board.name)+'</div><svg class="visual-svg" viewBox="0 0 310 245" aria-label="Grafo interativo: '+visEsc(board.name)+'">'+defs+paths+nodes+'</svg><div class="visual-metrics">'+visEsc(subtitle)+'</div></div>';
}
function visualLesson(id,step){
 const story=visualGetData(id,step);if(!story)return '';
 progress.visualSteps=progress.visualSteps||{};
 const key=id+":"+step;
 const phase=Math.min(3,Math.max(0,progress.visualSteps[key]||0));
 const f=story.frames[phase],build=progress.visualBuild?.[key+":"+phase]||null;
 const controls='<div class="visual-controls"><button class="btn ghost" data-v-action="prev" data-v-key="'+visEsc(key)+'" '+(phase===0?'disabled':'')+'>← Desmontar etapa</button><button class="btn secondary" data-v-action="next" data-v-key="'+visEsc(key)+'" '+(phase===3?'disabled':'')+'>Montar próxima →</button><button class="btn ghost" data-v-action="restart" data-v-key="'+visEsc(key)+'">↺ Reiniciar</button></div>';
 const buildInfo=build!==null?'<p class="visual-build-info">Modo construção: arestas tracejadas estão ausentes. Clique nelas para adicioná-las. Os valores abaixo são recalculados para o seu desenho.</p>':'<p class="visual-build-info">Clique em um vértice para examinar seu grau ou em “Montagem livre” para retirar e recolocar arestas.</p>';
 return '<section class="visual-card" aria-label="Demonstração interativa"><div class="visual-topline"><span class="visual-kicker">DEMONSTRAÇÃO INTERATIVA · ETAPA '+(step+1)+'</span><span class="visual-step-counter">'+(phase+1)+'/4</span></div><h3>'+visEsc(story.title)+'</h3><div class="visual-step-track">'+[0,1,2,3].map(i=>'<button aria-label="Ir para quadro '+(i+1)+'" data-v-action="goto" data-v-key="'+visEsc(key)+'" data-v-step="'+i+'" class="visual-dot '+(i===phase?'active':'')+'"></button>').join('')+'</div><p class="visual-frame-label">'+visEsc(f.label)+'</p><p class="visual-explainer">'+visEsc(f.note)+'</p><div class="visual-boards">'+f.boards.map((b,i)=>visualDrawGraph(b,'vis-'+id+'-'+step+'-'+phase+'-'+i,key,phase)).join('')+'</div>'+buildInfo+'<div class="visual-extra"><button class="btn ghost" data-v-action="build" data-v-key="'+visEsc(key)+'" data-v-phase="'+phase+'" data-v-board="'+visEsc(f.boards[0].graph)+'">'+(build===null?'◫ Montagem livre':'Restaurar grafo original')+'</button><span>Figuras esquemáticas e interativas; as operações formais são explicadas no texto.</span></div>'+controls+'</section>';
}
function visualHandleAction(target){
 const act=target.dataset.vAction;
 if(!act)return false;
 if(ui.route!=='lesson')return true;
 const key=target.dataset.vKey||ui.moduleId+":"+ui.step;
 const phase=Number(target.dataset.vPhase??progress.visualSteps?.[key]??0);
 progress.visualSteps=progress.visualSteps||{};
 progress.visualBuild=progress.visualBuild||{};
 if(act==='prev'||act==='next'||act==='restart'||act==='goto'){
  progress.visualSteps[key]=act==='prev'?Math.max(0,(progress.visualSteps[key]||0)-1):act==='next'?Math.min(3,(progress.visualSteps[key]||0)+1):act==='restart'?0:Math.max(0,Math.min(3,Number(target.dataset.vStep)));
 }else if(act==='build'){
  const slot=key+":"+phase+":"+target.dataset.vBoard;
  if(Object.hasOwn(progress.visualBuild,slot))delete progress.visualBuild[slot];
  else progress.visualBuild[slot]=[];
 }else if(act==='edge'){
  const slot=key+":"+phase+":"+target.dataset.vBoard;
  if(!Object.hasOwn(progress.visualBuild,slot)){progress.visualBuild[slot]=TGC_VISUAL_GRAPHS[target.dataset.vBoard].edges.map(visualEdgeKey)}
  const arr=progress.visualBuild[slot];const id=target.dataset.vEdge;
  progress.visualBuild[slot]=arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];
 }else if(act==='node'){
  const value=key+":"+phase+":"+target.dataset.vNode;
  window.TGC_VISUAL_PICK=window.TGC_VISUAL_PICK===value?'':value;
 }
 persist();render();return true;
}
document.addEventListener('click',function(e){const x=e.target.closest?.('[data-v-action]');if(x)visualHandleAction(x)});document.addEventListener('keydown',function(e){const x=e.target.closest?.('[data-v-action]');if(x&&(e.key==='Enter'||e.key===' ')){e.preventDefault();x.click()}});